// Mapache Neon Tokyo — pixel-art Tokyo at night in the Tokyo Night palette.
// Design: docs/design.md. Platform API: GUIDE.md (Gentle Shell themes folder).

const S = 4; // one art pixel, in window pixels (shared by every sprite)

const TN = {
  night: '#16161e', bg: '#1a1b26', storm: '#1f2335', hi: '#292e42', gutter: '#3b4261',
  black: '#414868', dark3: '#545c7e', comment: '#565f89', fgDark: '#a9b1d6', fg: '#c0caf5',
  blue: '#7aa2f7', cyan: '#7dcfff', mag: '#bb9af7', yel: '#e0af68', ora: '#ff9e64',
  red: '#f7768e', rose: '#ff007c', pink: '#ff86e5', green: '#9ece6a',
};
const WIN_WARM = ['#ff9ecf', '#ffd1ea', TN.pink, TN.yel];
const WIN_COOL = [TN.blue, TN.cyan, TN.mag, '#c9a6ff', '#9b5fd6'];
const NEON = [TN.rose, TN.cyan, TN.mag, TN.blue, TN.pink];

const pick = (arr, k) => arr[Math.min(arr.length - 1, Math.floor(k * arr.length))];
const snap = v => Math.round(v / S) * S;

// Scene-local clock: the intro is timed from the first frame this script draws,
// so it works whether or not the app resets `t` on launch (design §8, risk 1).
let first = null;

// ---------------------------------------------------------------- layout ---
// Everything static is built once per window size and reused every frame.
let layout = null, layoutKey = '';

function buildLayout(W, H) {
  const L = {
    farY: snap(H * 0.8), far: [], farLights: [], mid: [], windows: [], signs: [],
    stars: [],
  };

  // Stars in three sizes, denser and smaller toward the top.
  for (let i = 0; i < 120; i++) {
    const r = hash(i, 11);
    L.stars.push({
      x: hash(i, 12) * W, y: Math.pow(hash(i, 13), 1.5) * H * 0.62,
      s: r > 0.94 ? 3 : r > 0.7 ? 2 : 1, ph: hash(i, 14) * TAU, sp: 0.3 + hash(i, 15),
    });
  }

  // The centered close-up sees slightly past the wide shot's right edge.
  L.cityRight = W * 1.07 + S;
  // Far skyline: pale, taller toward the edges so the center stays calm.
  let x = -S * 6, i = 0;
  while (x < L.cityRight + S * 6) {
    const w = S * (6 + Math.floor(hash(i, 21) * 14));
    const edge = Math.abs((x + w / 2) / W - 0.5) * 2;
    const h = snap(H * (0.08 + 0.12 * hash(i, 22) + 0.1 * edge * edge));
    L.far.push({ x: snap(x), w, h, spire: hash(i, 23) > 0.78 });
    for (let k = 0; k < 7; k++) {
      if (hash(i, 30 + k) < 0.5) continue;
      L.farLights.push(light({
        x: snap(x + S + hash(i, 40 + k) * (w - 2 * S)),
        y: snap(L.farY - h + S * 2 + hash(i, 50 + k) * (h - S * 2)),
        id: i * 16 + k, col: pick(hash(i, 60 + k) > 0.5 ? WIN_WARM : WIN_COOL, hash(i, 70 + k)),
      }));
    }
    x += w + (hash(i, 24) > 0.8 ? S * 3 : 0);
    i++;
  }

  // Mid buildings: darker silhouettes with windows and neon signs.
  x = -S * 3; i = 0;
  while (x < L.cityRight + S * 3) {
    const w = S * (14 + Math.floor(hash(i, 61) * 16));
    const edge = Math.abs((x + w / 2) / W - 0.5) * 2;
    const h = snap(H * (0.1 + 0.09 * hash(i, 62) + 0.24 * edge * edge));
    const b = { x: snap(x), w, h, top: H - h, body: hex(mix(rgb('#1c1638'), rgb('#271c4c'), hash(i, 63))) };
    L.mid.push(b);

    const cols = Math.floor((w / S - 2) / 3), rows = Math.floor((h / S - 5) / 4);
    const warm = hash(i, 64) > 0.45;
    for (let c = 0; c < cols; c++) for (let r = 0; r < rows; r++) {
      const id = i * 1009 + c * 37 + r;
      if (hash(id, 1) > 0.55) continue; // not every slot is a window
      L.windows.push(light({
        x: b.x + S * (2 + c * 3), y: b.top + S * (4 + r * 4), id,
        col: pick(warm ? WIN_WARM : WIN_COOL, hash(id, 2)), tv: hash(id, 5) > 0.95,
      }));
    }

    // A vertical neon sign hanging off some taller buildings.
    if (h > H * 0.2 && hash(i, 65) > 0.45) {
      const chars = 3 + Math.floor(hash(i, 66) * 3);
      const glyphs = [];
      for (let k = 0; k < chars; k++) {
        let bits = Math.floor(hash(i * 7 + k, 67) * 512);
        if (bits.toString(2).split('1').length < 5) bits |= 0b010111010; // keep glyphs readable
        glyphs.push(bits);
      }
      const right = hash(i, 68) > 0.5;
      L.signs.push({
        x: right ? b.x + w - S * 2 : b.x - S * 3, y: b.top + S * (5 + Math.floor(hash(i, 69) * 4)),
        glyphs, col: pick(NEON, hash(i, 70)), id: i,
      });
    }
    x += w + (hash(i, 71) > 0.85 ? S * 2 : 0);
    i++;
  }

  L.skytreeX = snap(W * 0.24); L.towerX = snap(W * 0.67);
  L.skytreeY = snap(Math.max(H * 0.08, H * 0.68 - SKYTREE.h * S));
  // Use one roofline under BOTH feet. Previously a high roof hid the right
  // leg while the left ran down into a gap, reading as a stray slash.
  const half = TOKYO_TOWER.w * S / 2;
  L.towerRoof = L.farY;
  for (const b of L.far) {
    if (b.x < L.towerX + half && b.x + b.w > L.towerX - half)
      L.towerRoof = Math.min(L.towerRoof, L.farY - b.h - (b.spire ? 5 * S : 0));
  }
  buildNear(L, W, H);
  L.closePanX = CLOSE_Z * (L.perch[0] - W / 2);
  L.closePanY = CLOSE_Z * (L.perch[1] - MAPACHE.front.h * S / 2 - H / 2);
  return L;
}

// Near layer: elevated track, rooftops, the Mapache's ledge, power lines.
function buildNear(L, W, H) {
  L.trackY = snap(H * 0.8);
  L.pillars = [];
  for (let x = snap(W * 0.03); x < L.cityRight; x += S * 46) L.pillars.push(x);

  // Rooftops: a busy cluster at the left, low roofs in the middle, and the
  // ledge at the bottom-right where the Mapache ends up.
  L.roofs = [];
  let x = -S * 2, i = 0;
  while (x < W * 0.72) {
    const w = S * (18 + Math.floor(hash(i, 81) * 20));
    const left = x < W * 0.32;
    const h = snap(H * (left ? 0.07 + 0.07 * hash(i, 82) : 0.025 + 0.025 * hash(i, 82)));
    L.roofs.push({ x: snap(x), w, h, tank: left && hash(i, 83) > 0.4, ac: hash(i, 84) > 0.35, id: i });
    x += w;
    i++;
  }
  L.ledge = { x: snap(W * 0.72), w: W, h: snap(H * 0.16) };
  L.perch = [snap(W * 0.92), H - L.ledge.h];        // where the Mapache sits, near the right edge (S19)

  // Two utility poles with sagging wires across the left cluster.
  const p1 = [snap(W * 0.05), snap(H * 0.66)], p2 = [snap(W * 0.36), snap(H * 0.72)];
  L.poles = [p1, p2];
  L.wires = [0, 1, 2].map(k => {
    const pts = [], dy = k * S * 2;
    for (let s = 0; s <= 24; s++) {
      const u = s / 24;
      pts.push(lerp(p1[0], p2[0], u), lerp(p1[1], p2[1], u) + dy + Math.sin(u * Math.PI) * H * 0.035);
    }
    return pts;
  });

  L.sakura = buildSakura(W, H);
  const sources = L.sakura.flatMap(b => b.flowers).filter(f => f.x > S && f.y > S && f.y < H - S);
  L.petals = [];
  for (let i = 0; i < 34; i++) {
    const r = hash(i, 91), tier = r > 0.8 ? 2 : r > 0.45 ? 1 : 0; // 0 far, 1 mid, 2 near
    const source = i % 3 === 0 && sources.length ? pick(sources, hash(i, 96)) : null;
    L.petals.push({ i, tier, source, x0: hash(i, 92), y0: hash(i, 93), sp: hash(i, 94), spin: 0.6 + hash(i, 95) * 1.6 });
  }
}

// Symmetric silhouettes, not symmetric shading. A [height, row] repeats
// a course of steel or rock; all expansion happens before the first frame.
function centeredArt(courses, palette) {
  const rows = [];
  for (const course of courses) {
    if (typeof course === 'string') rows.push(course);
    else rows.push(...Array(course[0]).fill(course[1]));
  }
  const w = Math.max(...rows.map(row => row.length));
  return pixels(rows.map(row => ('.'.repeat((w - row.length) >> 1) + row).padEnd(w, '.')), palette);
}
const tone = (a, b, k) => hex(mix(rgb(a), rgb(b), k));

// Broad fields of peach save pixel runs for the craters and rose-gold limb.
const MOON = centeredArt([
  'hhhhhhhhh', 'hhhhhhhhhhppppp', 'hhhpppppppppppppppp',
  'hhppppppppppppppppppp', 'hppppppppppppcpppppppps',
  'pppppppppppppcccpppppppps', 'pppppcppppppppccpppppppps',
  'ppppcccppppppppppppppppppps', 'pppppccppppppppppppppppppps',
  [2, 'pppppppppppppppppppppppppppps'], [2, 'pppppppppppppppppppppppppppppps'],
  'ppppppppppppppppppppppppccpppps', 'pppppppppppppppppppppppcccpcpps',
  'ppppppppppppppppppppppppccpppss', [2, 'pppppppppppppppppppppppppppppss'],
  'ppppppppccppppppppppppppppppsss', 'pppppppccccpppppppppppppppppsss',
  'pppppppcccspppppppppppppppsss', 'ppppppppssppcpppppppppppppsss',
  'pppppppppppcccpspppppppssss', 'ppppppppppssspppppppppsssss',
  'ppppppppppppppppppppsssss', 'pppppppppppppppppppssssss',
  'pppppppppppppppssssss', 'pppppppppppssssssss', 'sssssssssssssss', 'sssssssss',
], {
  h: shade(TN.ora, 0.8), p: tone(shade(TN.ora, 0.62), shade(TN.red, 0.64), 0.48),
  s: tone(shade(TN.ora, 0.46), TN.red, 0.25), c: tone(TN.red, TN.fgDark, 0.48),
});

// Two or three piled banks, with a pink-lilac crest only on the high edge.
const MIST_INK = { h: tone(shade(TN.pink, 0.52), TN.mag, 0.26), v: TN.mag,
  m: tone(TN.mag, '#9b5fd6', 0.68), d: '#724fa1' };
const CLOUDS = [
  pixels([
    '........................hhhhhhhh', '.....................vvvvvvvvvvvvvv',
    '...........hhhhh....vvvvvvvvvvvvvvvvv', '........vvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv',
    '......mmmmvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv...hhh',
    '...mmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmvvvvvv',
    'mmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmm',
    '.......ddddddddddddddddddddddddddddddddddmmmmmm', '.............dddddddddddddddddddd',
  ], MIST_INK),
  pixels([
    '.............hhhhhhhh', '..........vvvvvvvvvvvvvv', '.........vvvvvvvvvvvvvvvvv.......hhhhh',
    '.....hhhhvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv', '...vvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv',
    'mmmmmmmmmmmmmmmmmmvvvvvvvvvvvvvvvvvvvvvvvvvvvv',
    '....mmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmm',
    '.......ddddddddddddddmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmm',
    '...................dddddddddddddddddddddddddddd',
  ], MIST_INK),
];
// Sprite, phase across the sky, height, wind (window px/s), opacity, mirror.
const CLOUD_BANDS = [
  [1, 0.14, 0.095, 5, 0.59, true], [0, 0.83, 0.13, 6, 0.55, false],
  [0, 0.38, 0.235, 8, 0.65, true], [1, 0.95, 0.315, 10, 0.58, false],
  [1, 0.07, 0.385, 7, 0.53, true],
];

// Fuji: a broken lip of snow feeds narrow gullies. Long, unbroken runs
// describe the lit western face and the violet eastern face. At the foot
// the two colours converge AND lose opacity; no opaque bottom stripe.
function fujiArt() {
  const pal = { w: shade(TN.fg, 0.88), i: tone(TN.fg, TN.mag, 0.42),
    l: tone(TN.blue, TN.mag, 0.68), v: '#8972cc', d: '#7055a7' };
  const summit = ['wwwwwii', 'wwwwwwwiii', 'wwwwwwwiiii', 'wwwwwwiwwiii', 'wwwwiwwiiwiiii',
    'wwwwiwwwiiwiiiiv', 'wwwllwwwiiwiiiivv', 'wwlllwwliiwviiivvv', 'wllllwwllivvviiivvvv',
    'lllllwwllivvviidddvvv', 'llllwllllivvvviddddvvv', 'lllllllllivvvvidddddvvv',
    'lllllllllivvvvdddddddvvv', 'lllllllllvvvvdddddddddvvv'];
  // The crease inside each face trails downhill, broadening below the ice.
  const slopes = [[11, 2, 7, 9], [12, 3, 8, 10], [13, 3, 9, 11], [14, 4, 10, 13],
    [16, 4, 12, 14], [17, 5, 13, 16], [19, 5, 15, 17], [22, 5, 16, 20],
    [24, 6, 18, 22], [27, 6, 20, 25], [30, 6, 23, 28], [33, 6, 26, 31]]
    .map(([sun, ridge, flank, shade]) => [2, 'l'.repeat(sun) + 'v'.repeat(ridge)
      + 'l'.repeat(flank) + 'd'.repeat(shade)]);
  const skirts = [];
  for (let i = 0; i < 12; i++) {
    // Two uppercase ranges keep these haze colours separate from the summit.
    const k = (i + 1) / 12, left = String.fromCharCode(65 + i), shadow = String.fromCharCode(78 + i);
    const a = Math.round(255 * (1 - smoothstep(0, 1, k))).toString(16).padStart(2, '0');
    pal[left] = tone(pal.l, '#9b5fd6', k) + a; pal[shadow] = tone(pal.d, '#9b5fd6', k) + a;
    skirts.push(left.repeat(68 + i * 4) + shadow.repeat(33 + i * 3));
  }
  return centeredArt(summit.concat(slopes, skirts), pal);
}
const FUJI = fujiArt();

// Skytree: needle, icy spiral gallery, broad Tembo Deck, tapering tripod.
const SKYTREE = centeredArt([
  [8, 'w'], [6, 'c'], [4, 'b'], 'www', [6, 'ccc'],
  'wwwww', 'ccccccc', 'bbbbb', [8, 'ccb'], 'www', [3, 'bbb'],
  'wwwwwww', 'wwwwwwwww', 'ccccccccccc', 'bbbbbbbbb', 'vvvvv',
  [7, 'ccbb'], [3, 'bccc'], [4, 'ccbbb'], [4, 'cc.vb'], 'ccccccc',
  [5, 'cc..vbb'], 'bbbbbbbbb', [5, 'bc..v..bb'], 'vbbbbbbbbbbbv',
], { w: shade(TN.cyan, 0.8), c: TN.cyan, b: TN.blue, v: TN.comment });

// Tokyo Tower: alternating vermilion and ivory on the aerial, two amber
// lantern decks, open X-braces and a flared arch at street level.
const TOKYO_TOWER = centeredArt([
  [4, 'p'], [3, 'r'], [2, 'p'], [3, 'r'], 'ppp', [3, 'ooo'], 'ppp',
  'yyyyy', 'wwwww', 'rrrrr', [3, 'orr'], 'o.o', 'oro', 'ppp',
  'o.r.o', 'oo.oo', 'r.r.r', 'oo.oo', 'ooooo',
  'rr...rr', 'r.r.r.r', 'o..r..o', 'r.r.r.r', 'rr...rr', 'ooooooo',
  'yyyyyyyyy', 'wwwwwwwww', 'rryyyyyrr', 'rrrrrrrrr',
  'oo.....oo', 'or.r.r.ro', 'or..r..ro', 'rr..o..rr', 'rr.r.r.rr',
  'oo.r...r.oo', 'orr.....rro', 'ooooooooooo', 'rr.r...r.rr',
  'rr...r.r...rr', 'rr....r....rr', 'rr...r.r...rr', 'rr..r.....r..rr',
  'rr.r.......r.rr', 'ooooooooooooooo', 'oorrr.....rrroo', 'orr.........rro',
  'orr...........rro', 'rrr.............rrr', 'ssrr...........rrss',
], { r: '#df5846', s: tone(TN.black, TN.red, 0.38), o: TN.ora, p: shade(TN.ora, 0.77),
  y: TN.yel, w: shade(TN.yel, 0.68) });

// ---------------------------------------------------------------- sprites --
// Neon rose petals: three sizes, three tumble frames each (open, half, edge-on).
const PP = { r: TN.rose, h: TN.pink, d: '#a3004f' };
const PETALS = [
  [pixels(['.rh', 'drr'], PP), pixels(['rrh'], PP), pixels(['rh'], PP)],
  [pixels(['..rh', '.rrh', 'rrr.', 'dr..'], PP), pixels(['.rrh', 'drr.'], PP), pixels(['rrh'], PP)],
  [pixels(['....rh.', '..rrrhh', '.rrrrh.', 'rrrrh..', 'drr....'], PP),
   pixels(['...rrh.', '.rrrrhh', 'ddrrr..'], PP),
   pixels(['..rrh', 'ddrr.'], PP)],
];

// One five-lobed corolla, shaded for three depths. Only the front flowers
// catch the pale rim light; one magenta pixel marks each open center.
const SAKURA_PAL = {
  b: hex(mix(rgb(TN.storm), rgb(TN.rose), 0.3)),
  c: TN.rose,
  s: hex(mix(rgb(TN.rose), rgb(TN.storm), 0.35)),
  p: hex(mix(rgb(TN.pink), rgb(TN.rose), 0.35)), l: TN.pink, h: '#ffd6f6',
};
const SAKURA_FACE = [
  '...hh', '...lll', 'hl.lll.ll', 'llllcllll', '.lllllll', '..lllll', '.lll.lll', '..ll.ll',
];
// Behind these open faces the overlapping lobes are cupped, so less of the
// throat is visible. Their edges give each spray a round, irregular outline.
const SAKURA_HALF = ['..ppp', '.pppp.pp', 'pppppppp', 'pppcppp', '.pppppp', '..pp.pp'];
const SAKURA_SHADE = ['...sss', '.sssss', 'ssssssss', 'ssssssss', '.ssssss', '..ss.ss'];
const SAKURA_BUD = ['.hh', 'ppp', '.s'];

// Work in art pixels measured inward from each edge. Bake all overlaps at
// load time so a frame only draws one sprite per corner.
function sakuraCanopy(w, h, lower, limbs, sprays) {
  const rows = Array(h).fill('.'.repeat(w)), flowers = [];
  function ink(x, y, run) {
    if (y < 0 || y >= h || x >= w) return;
    const visible = run.slice(Math.max(0, -x), w - x);
    if (!visible) return;
    x = Math.max(0, x);
    rows[y] = rows[y].slice(0, x) + visible + rows[y].slice(x + visible.length);
  }
  const screenY = y => lower ? h - 1 - y : y;
  for (const limb of limbs) for (let j = 1; j < limb.length; j++) {
    const [x, y, thick] = limb[j - 1], [x1, y1, thin] = limb[j];
    const n = Math.max(Math.abs(x1 - x), Math.abs(y1 - y));
    for (let i = 0; i <= n; i++) {
      const k = i / n, u = Math.round(lerp(x, x1, k)), v = Math.round(lerp(y, y1, k));
      const width = Math.round(lerp(thick, thin, k));
      for (let r = 0; r < width; r++) ink(u, screenY(v + r), 'b'.repeat(width));
    }
  }
  function stamp(shape, x, y) {
    shape.forEach((row, r) => {
      for (const run of row.matchAll(/[a-z]+/g)) ink(x + run.index, y + r, run[0]);
    });
  }
  for (const [u, v, side] of sprays) {
    if (u >= (lower ? 60 : 77) || v >= (lower ? 40 : 46)) continue;
    const y = screenY(v), tilt = (u + v) % 2 ? 1 : -1;
    stamp(SAKURA_SHADE, u - 4 - side * 6, y - 2 + tilt * 2);
    stamp(SAKURA_HALF, u - 4 + side * 6, y - 3 - tilt * 2);
  }
  for (const [u, v, side, lit] of sprays) {
    const y = screenY(v), x = u + Math.round(6 * hash(u, v) - 3);
    stamp(SAKURA_FACE, x - 4, y - 3);
    if (lit) stamp(SAKURA_BUD, x + 4 * side, y - 2);
    flowers.push({ u: x, v: y, lit });
  }
  return { art: pixels(rows, SAKURA_PAL), flowers, lower };
}
const SAKURA = [
  sakuraCanopy(93, 58, false, [
    [[1,-4,4],[10,6,4],[23,16,4],[39,20,3],[57,14,2],[74,15,1],[87,10,1]],
    [[-2,5,4],[7,13,4],[12,24,3],[8,38,2],[14,51,1]],
    [[23,17,3],[31,26,2],[42,30,2],[56,39,1]], [[39,20,2],[47,8,2],[56,0,1]],
    [[9,7,2],[23,5,2],[32,0,1]], [[67,15,2],[73,23,1]],
  ], [[4,7,-1], [23,3,1], [2,19,-1], [12,29,-1], [6,41,1], [13,51,-1,true],
      [30,20,-1], [46,32,-1], [50,7,1], [65,16,1,true], [85,12,1]]),
  sakuraCanopy(79, 51, true, [
    [[-2,1,4],[11,9,4],[20,20,4],[34,25,3],[44,33,2],[62,32,1],[71,38,1]],
    [[9,8,3],[24,9,3],[39,5,2],[57,8,1]], [[20,20,3],[17,30,2],[24,45,1]],
    [[2,4,3],[6,20,2],[2,37,1]], [[43,33,2],[49,43,1]],
  ], [[4,3,1], [19,10,-1], [47,7,1], [2,29,-1], [19,38,1,true],
      [30,23,-1], [46,32,-1], [49,41,1], [69,37,-1,true]]),
];

function buildSakura(W, H) {
  return SAKURA.map(({ art, flowers, lower }) => {
    // Crop at the attached edge on small windows; never rescale the S grid.
    const x = Math.min(-S, W * (lower ? 0.25 : 0.29) - art.w * S);
    const inset = Math.min(-S, H * (lower ? 0.25 : 0.29) - art.h * S);
    const y = lower ? H - inset - art.h * S : inset;
    const anchors = flowers.map(f => ({ x: x + f.u * S, y: y + f.v * S, lit: f.lit }));
    return { x, y, art, flowers: anchors, lights: anchors.filter(f => f.lit), phase: lower ? 2.8 : 0.4 };
  });
}

// The branches stay out of the close-up and fade in once the camera has
// pulled back to the wide view.
// (Times are offsets from WIDE_AT, which is declared further down.)
const sakuraIn = () => WIDE_AT - 0.5;
function drawSakura(g, L, t) {
  const a = smoothstep(sakuraIn(), WIDE_AT + 1.5, t);
  if (a <= 0) return;
  for (const b of L.sakura) {
    const dx = 1.4 * Math.sin(t * 0.52 + b.phase), dy = 2.6 * noise(b.phase, t * 0.27);
    // Keep adjacent sprite rows touching during the sway. Snap only the
    // final blit to physical window pixels, never the motion to the S grid.
    g.pixels(b.art, Math.round(b.x + dx), Math.round(b.y + dy), S, a);
    for (const f of b.lights) {
      g.glow(f.x + dx, f.y + dy, 7 * S, TN.rose, a * (0.16 + 0.08 * Math.sin(t * 0.9 + f.x * 0.055)));
    }
  }
}

// Lens-close rose petal, built once: an obovate blade whose top edge rolls
// back on the right (the paler underside shows above a dark crease), a cup
// lit from the upper left, and faint veins fanning out of a narrow claw.
function wipePetalArt(w, h) {
  const centre = v => w / 2 - 0.5 + 1.4 * Math.sin(v * Math.PI) - 1.2 * v * v; // a gentle bow
  const half = v => {
    const cap = v < 0.38 ? Math.sqrt(Math.max(0, 1 - ((0.38 - v) / 0.38) ** 2)) : 1;
    const taper = v < 0.38 ? 1 : 1 - 0.88 * ((v - 0.38) / 0.62) ** 1.5;
    return (w / 2 - 0.5) * cap * taper;
  };
  const shape = [];
  for (let y = 0; y < h; y++) {
    shape.push([]);
    for (let x = 0; x < w; x++) {
      // A soft wave on the rim keeps the top from reading as a geometric arc.
      const v = (y + 0.5 + 0.9 * Math.sin(x * 0.55 + 1)) / h;
      shape[y].push(v > 0 && Math.abs(x - centre(v)) <= half(v));
    }
  }
  const inside = (x, y) => y >= 0 && y < h && x >= 0 && x < w && shape[y][x];
  const rows = [];
  for (let y = 0; y < h; y++) {
    let row = '';
    for (let x = 0; x < w; x++) {
      if (!inside(x, y)) { row += '.'; continue; }
      const v = (y + 0.5) / h, u = (x - centre(v)) / Math.max(0.5, half(v));
      let lip = 0; while (inside(x, y - lip - 1)) lip++;       // depth below the rim
      let side = 0; while (inside(x + side + 1, y)) side++;    // depth from the right edge
      // The reflexed edge: widest at the top right, wrapping a little way
      // down the right side, then a dark crease where it folds back.
      const roll = Math.max(1 + Math.round(4 * smoothstep(-0.25, 0.85, u)),
        v < 0.5 ? Math.round(9 * (1 - v / 0.5)) - side : 0);
      if (lip < roll || (v < 0.5 && side < 3 * (1 - v / 0.5))) {
        row += lip === 0 && u < 0.1 ? 'w' : 'h'; continue;
      }
      if (!inside(x - 1, y) || !inside(x + 1, y) || !inside(x, y + 1)) { row += 'k'; continue; }
      if ((lip === roll && u > -0.45) || (v < 0.55 && side < 4.2 * (1 - v / 0.55) + 0.5)) {
        row += 'D'; continue;                                   // shadow under the roll
      }
      // Cup shading: bright upper-left, deep toward the right and the claw.
      // Cup shading: the rim is lit, the blade deepens toward the claw and
      // the right, and the edges stay a touch brighter than the hollow.
      let s = 0.86 - 0.78 * v - 0.2 * u + 0.12 * Math.abs(u) - 0.4 * Math.max(0, v - 0.72);
      if (lip >= 3 && lip <= 5 && u < -0.25 && u > -0.85) s += 0.32;    // sheen below the lit rim
      const bx = w / 2 - 1.5, by = h + 1, ang = Math.atan2(x - bx, by - y);
      const vein = [-0.3, 0.02, 0.32].some(a => Math.abs(ang - a) < 0.035);
      // Banded, not dithered, and veins only near the claw: a rotated run
      // costs path points, so fewer runs keep the wipe frames under 3 ms.
      if (vein && v > 0.55 && v < 0.92) s += 0.17;
      row += s > 0.98 ? 'h' : s > 0.56 ? 'p' : s > 0.24 ? 'r' : s > 0.04 ? 'd' : 'D';
    }
    rows.push(row);
  }
  return rows;
}
