// `over` draws `top` over `base` wherever `top` is not transparent.
function over(base, top) {
  return base.map((row, y) => {
    const t = top[y] || '';
    let out = '';
    for (let x = 0; x < Math.max(row.length, t.length); x++) {
      const c = t[x];
      out += c && c !== '.' ? c : row[x] || '.';
    }
    return out;
  });
