// Sparse layer: [row, column, text] entries on a 20-row body grid.
function layer(entries, rows = 20) {
  const out = Array(rows).fill('');
  for (const [y, x, s] of entries) out[y] = over([out[y].padEnd(x, '.')], ['.'.repeat(x) + s])[0];
  return out;
