  const at = (x, y) => (g[y] && g[y][x]) || '.';
  g.forEach(r => r.forEach((c, x) => { if (x >= minCol && (c === 'T' || c === 't')) r[x] = '.'; }));
  for (let pass = 0; pass < 3; pass++) {
    g.forEach((r, y) => r.forEach((c, x) => {
      if (c !== 'k' || x < minCol) return;
      const solid = [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([dx, dy]) => !'.k'.includes(at(x + dx, y + dy)));
      if (!solid) r[x] = '.';
    }));
  }
  return g.map(r => r.join(''));
