  [11, 5, 'RPPR'], [10, 25, 'RPR'], [13, 9, 'RPPPPPPPPPPPPPR'],
]);
const OUTFIT = 'bomber'; // 'bomber' or 'hoodie'
const OUTFITS = { hoodie: HOODIE, bomber: BOMBER };

function buildMapache(body) {
  const facing = (head, b, tail) => mapacheArt(head, over(tail, b));
  const away = (head, b, tail) => mapacheArt(head, over(b, tail));
  return {
    front: facing(FRONT_BROW.concat(FRONT_EYES, FRONT_MUZZLE), body.front, TAIL_UP),
    frontBlink: facing(BLINK_BROW.concat(BLINK_EYES, FRONT_MUZZLE), body.front, TAIL_UP),
    threeQuarter: facing(QUARTER_HEAD, body.quarter, TAIL_UP),
    side: facing(SIDE_HEAD, body.side, TAIL_UP.map(r => r.slice(3))),
    back: away(BACK_HEAD, body.back, TAIL_CURL),
    backTilt: away(TILT_HEAD, body.back, TAIL_CURL_LIFT),
    backTail: away(BACK_HEAD, body.back, TAIL_CURL_LIFT),
    backArm: away(BACK_HEAD, body.backArm, TAIL_CURL),
  };
}
const MAPACHE = buildMapache(OUTFITS[OUTFIT]);

const ROSE_PAL = { ...PP, k: '#290f2a', g: '#245950', l: '#438579' };
const ROSE_STEM = ['..kgk..', '.lkgklk', '.kllglk', '..kkgk.', '...kgk.', '....g..'];
const ROSE_ROWS = [
  ['..kk.k.', '.khrkrk', 'krdhrdk', 'krrdrdk', '.krrdk.', '..kdk..', ...ROSE_STEM],
  ['..kk.k.', '.khhkhk', 'khrhrrk', 'krrdhrk', '.khrrk.', '..kdk..', ...ROSE_STEM],
];
const ROSE = ROSE_ROWS.map(rows => pixels(rows, ROSE_PAL));

// Grip in art pixels relative to Mapache's bottom-center; rose cell (4, 9)
// lies in the paw. Use this same pivot when the flower leaves the hand.
const ROSE_ATTACH = { x: -12, y: -13 };
const GRIP_QUARTER = { x: -11, y: -12 }, GRIP_SIDE = { x: 0, y: -6 };
const GRIP_LOW = { x: -12, y: -7 };
function drawRose(g, x, y, frame = 0, alpha = 1, flip = false) {
  const art = ROSE[frame];
  g.pixels(art, x - (flip ? art.w - 4 : 4) * S, y - 9 * S, S, alpha, flip);
}

function drawMapache(g, x, y, pose, alpha = 1, flip = false) {
  const art = MAPACHE[pose];
  g.pixels(art, x - art.w * S / 2, y - art.h * S, S, alpha, flip);
}

// Temporary proof sheet: all poses, then the two isolated rose frames.
const DEBUG_LINEUP = false;
const LINEUP_POSES = Object.keys(MAPACHE);
function drawLineup(g, W, H) {
  const stride = (MAPACHE.front.w + 3) * S, roseStride = (ROSE[0].w + 3) * S;
  const width = LINEUP_POSES.length * stride + ROSE.length * roseStride;
  g.save();
  g.translate(W / 2, H * 0.45);
  g.scale(Math.min(1, W / width));
  let left = -width / 2;
  for (const pose of LINEUP_POSES) {
    drawMapache(g, left + stride / 2, MAPACHE.front.h * S / 2, pose);
    left += stride;
  }
  for (const flower of ROSE) {
    g.pixels(flower, left + (roseStride - flower.w * S) / 2, -flower.h * S / 2, S);
    left += roseStride;
  }
  g.restore();
}

// ---------------------------------------------------------------- camera ---
// The petal glides in and out over ~0.7 s each so it reads smoothly at 24 fps;
// the hold (COVER_AT..REVEAL_AT) and the pull-back timing are unchanged.
const WIPE_IN = 10.75, COVER_AT = 11.5, REVEAL_AT = 11.76, WIPE_OUT = 12.45;
// Keep the wide shot at 15 s so the idle and first preview glance stay on cue.
const CLOSE_Z = 2.4, PULL_AT = COVER_AT + 0.05, WIDE_AT = 15;
const wideCam = { z: 1, x: 0, y: 0 }, camState = { ...wideCam };
function camera(lt) {
  if (lt >= WIDE_AT) return wideCam;
  const close = 1 - smoothstep(PULL_AT, WIDE_AT, lt);
  // Zoom in log space so the scale changes at an even perceived rate (a
  // linear zoom rushes at the end). Pan in scaled window pixels: the sprite's
  // midpoint, not its feet, is centered. Tying the pan to the zoom keeps the
  // ledge attached and the Mapache on a straight path to its corner.
  const drift = smoothstep(1.5, 2, lt) * (1 - smoothstep(4.5, 5, lt));
  camState.z = Math.pow(CLOSE_Z, close);
  const k = (camState.z - 1) / (CLOSE_Z - 1);
  camState.x = layout.closePanX * k + 3 * drift * Math.sin(lt);
  camState.y = layout.closePanY * k + 2 * drift * Math.sin(lt * 1.3);
  return camState;
}

function applyCamera(g, cam, parallax, W, H) {
  const z = 1 + (cam.z - 1) * parallax;
  g.translate(W / 2 - cam.x * parallax, H / 2 - cam.y * parallax);
  g.scale(z);
  g.translate(-W / 2, -H / 2);
}

// ---------------------------------------------------------- choreography ---
const RELEASE = 9.25, TURN_BEAT = 0.45;
const TURN = ['front', 'threeQuarter', 'side', 'back'];
const breath = t => 1 + Math.sin(t * 1.6);
// One glance per 27.5 s block. Offsetting starts by 0–7.5 s gives
// intervals of 20–35 s, with no timers, catch-up loops or frame history.
// Returns seconds into the current glance, or -1 between glances.
const GAZE = 2.5;
function glanceAge(idle) {
  const block = Math.floor(idle / 27.5);
  if (block <= 0) return -1;
  const age = idle - block * 27.5 - (block === 1 ? 0 : 7.5 * hash(block, 112));
  return age >= 0 && age < 4 * TURN_BEAT + GAZE ? age : -1;
}
function poseAt(t) {
  if (t < 5) return (t > 1.72 && t < 1.9) || (t > 4.1 && t < 4.28) ? 'frontBlink' : 'front';
  if (t < 7) return TURN[Math.min(3, Math.floor((t - 5) / TURN_BEAT))];
  if (t < 9) return t > 7.15 && t < 7.86 ? 'backTail' : 'back';
  if (t < 11) return 'backArm';
  if (t < WIDE_AT) return 'back';

  const idle = t - WIDE_AT, age = glanceAge(idle);
  if (age >= 0) {
    if (age < TURN_BEAT || age >= 3 * TURN_BEAT + GAZE) return 'side';
    if (age < 2 * TURN_BEAT || age >= 2 * TURN_BEAT + GAZE) return 'threeQuarter';
    return age >= 2 && age < 2.18 ? 'frontBlink' : 'front';
  }
  if (Math.sin(idle * 0.56 + 0.7 * Math.sin(idle * 0.18)) > 0.94) return 'backTilt';
  return Math.sin(idle * 1.2 + 0.45 * Math.sin(idle * 0.47)) > 0.45 ? 'backTail' : 'back';
}

// Fall displacement from the lowered paw, in world pixels. The blossom is
// six art pixels above the grip and swings around it as the stem turns.
const fallX = u => -18 * S * u, fallY = (u, H) => H * 0.38 * u * u;
const fallAngle = u => -3.3 * u;
function drawHero(g, L, H, t) {
  const x = L.perch[0], y = L.perch[1] + breath(t), pose = poseAt(t);
  // The rose stays in the paw through the intro and, after it was dropped,
  // is back in the paw whenever the Mapache turns to look at the viewer.
  const age = t >= WIDE_AT ? glanceAge(t - WIDE_AT) : -1;
  if (t < RELEASE || age >= 0) {
    const frame = Math.floor(t * 2.4) % 2;
    if (pose === 'side') {
      // The near paw crosses the torso in profile; keep the bloom in view.
      drawMapache(g, x, y, pose);
      drawRose(g, x + GRIP_SIDE.x * S, y + GRIP_SIDE.y * S, frame);
      return;
    }
    const grip = pose === 'threeQuarter' ? GRIP_QUARTER : pose === 'backArm' ? GRIP_LOW : ROSE_ATTACH;
    drawRose(g, x + grip.x * S, y + grip.y * S, frame);
  } else if (t < 11) {
    const u = (t - RELEASE) / (11 - RELEASE);
    g.save();
    g.translate(x + GRIP_LOW.x * S + fallX(u), L.perch[1] + breath(RELEASE) + GRIP_LOW.y * S + fallY(u, H));
    g.rotate(fallAngle(u));
    drawRose(g, 0, 0, Math.floor(t * 2.4) % 2);
    g.restore();
  }
  drawMapache(g, x, y, pose);
}

// Screen-space like the ambient petals. At release the close-up is fixed
// and centered, so project each launch point once for its whole trajectory.
const SHED_AT = [0.08, 0.24, 0.4, 0.53];
function drawLoosePetals(g, W, H, t) {
  const drop = (t - RELEASE) / (11 - RELEASE);
  for (let i = 0; i < SHED_AT.length; i++) {
    const u = SHED_AT[i], age = (drop - u) * (11 - RELEASE);
    if (age < 0 || age >= 0.75) continue;
    const angle = fallAngle(u);
    const dx = GRIP_LOW.x * S + fallX(u) + 6 * S * Math.sin(angle);
    const dy = MAPACHE.front.h * S / 2 + breath(RELEASE) + GRIP_LOW.y * S + fallY(u, H) - 6 * S * Math.cos(angle);
    const x = W / 2 + CLOSE_Z * dx - age * (42 + 12 * i) + 5 * Math.sin(age * 7 + i);
    const y = H / 2 + CLOSE_Z * dy + age * (18 + 62 * age);
    // Centered on its frame so the tumble never shifts the petal sideways.
    const art = PETALS[1][Math.floor(age * 5 + i) % 3];
    const a = smoothstep(0, 0.08, age) * (1 - smoothstep(0.4, 0.75, age));
    g.pixels(art, x - art.w * S / 2, y - art.h * S / 2, S, a);
  }
}

// ----------------------------------------------------------------- draw ----
function drawStars(g, L, lt) {
  for (const s of L.stars) {
    const a = 0.25 + 0.6 * (0.5 + 0.5 * Math.sin(lt * s.sp + s.ph));
    if (s.s === 3) { // a little cross for the brightest ones
      g.rect(s.x - 1, s.y - 3, 2, 6, TN.fg, a);
      g.rect(s.x - 3, s.y - 1, 6, 2, TN.fg, a);
    } else {
      g.rect(s.x, s.y, s.s + 1, s.s + 1, s.s === 2 ? TN.fg : TN.comment, a);
    }
  }
}

function drawCityGlow(g, W, H, lt) {
  g.gradient(0, H * 0.4, W, H * 0.6, 180, '#4a1d7a00', '#8a2a8a77');
  g.glow(W * 0.2, H * 0.82, W * 0.34, '#9b5fd6', 0.16);
  g.glow(W * 0.6, H * 0.86, W * 0.38, '#ff6fb5', 0.13 + 0.03 * Math.sin(lt * 0.2));
  g.glow(W * 0.92, H * 0.8, W * 0.28, TN.blue, 0.14);
}

function drawMoonAndClouds(g, W, H, lt) {
  const x = W * 0.82, y = Math.max(H * 0.17, (MOON.h / 2 + 2) * S);
  g.glow(x, y, MOON.w * S * 0.94, TN.red, 0.15 + 0.035 * Math.sin(lt * 0.29));
  g.pixels(MOON, x - MOON.w * S / 2, y - MOON.h * S / 2, S);
  for (const [index, phase, band, wind, alpha, flip] of CLOUD_BANDS) {
    const art = CLOUDS[index], width = art.w * S, span = W + width;
    g.pixels(art, (phase * span + lt * wind) % span - width, band * H, S, alpha, flip);
  }
}

function drawTowers(g, L, lt, leftEdge) {
  const sx = L.skytreeX, sy = L.skytreeY, tx = L.towerX, ty = L.towerRoof - TOKYO_TOWER.h * S;
  if (sx + 14 * S > leftEdge) { // The Skytree is entirely off camera in the intro.
    g.glow(sx, sy + 40 * S, 14 * S, TN.cyan, 0.16 + 0.025 * Math.sin(lt * 0.78));
    const foot = sy + SKYTREE.h * S;
    if (foot < L.farY) g.rect(sx - SKYTREE.w * S / 2, foot, SKYTREE.w * S, L.farY - foot, TN.black);
    g.pixels(SKYTREE, sx - SKYTREE.w * S / 2, sy, S, 0.93);
    g.rect(sx - S / 2, sy - S, S, S, TN.red, 0.22 + 0.76 * smoothstep(-0.15, 0.95, Math.sin(lt * 1.34)));
  }
  g.glow(tx, ty + 38 * S, 13 * S, TN.ora, 0.16 + 0.025 * Math.sin(lt * 0.65 + 1));
  const width = TOKYO_TOWER.w * S, left = tx - width / 2;
  g.rect(left, L.towerRoof, width, L.farY - L.towerRoof, '#2b2054');
  g.rect(left, L.towerRoof, width, S, '#46307a');
  g.pixels(TOKYO_TOWER, left, ty, S, 0.95);
  g.rect(tx - S / 2, ty - S, S, S, TN.red, 0.22 + 0.76 * smoothstep(-0.15, 0.95, Math.sin(lt * 1.15 + 2)));
}

// The part of a parallax layer the window shows, in that layer's world
// pixels. Shapes wholly outside it are skipped: a cheaper frame keeps the
// scene at the full 24 fps, and nothing visible changes.
const view = { l: 0, r: 0, t: 0, b: 0 };
function viewOf(cam, parallax, W, H) {
  const z = 1 + (cam.z - 1) * parallax, px = cam.x * parallax, py = cam.y * parallax;
  view.l = (px - W / 2) / z + W / 2 - S; view.r = (W / 2 + px) / z + W / 2 + S;
  view.t = (py - H / 2) / z + H / 2 - S; view.b = (H / 2 + py) / z + H / 2 + S;
  return view;
}
const seen = (v, x, y, w, h) => x + w > v.l && x < v.r && y + h > v.t && y < v.b;

function drawFar(g, L, lt, v) {
  for (const b of L.far) {
    if (b.x + b.w < v.l || b.x > v.r) continue;
    g.rect(b.x, L.farY - b.h, b.w, b.h + 400, '#2b2054');
    g.rect(b.x, L.farY - b.h, b.w, S, '#46307a');               // rim lit by the city glow
    if (b.spire) {
      const sx = b.x + snap(b.w / 2), sy = L.farY - b.h - S * 4;
      g.rect(sx, sy, S, S * 4, '#46307a');
      const a = 0.3 + 0.7 * smoothstep(0, 1, 0.5 + 0.5 * Math.sin(lt * 1.2 + b.x));
      g.rect(sx, sy - S, S, S, TN.red, a * 0.8);
    }
  }
  for (const w of L.farLights) {
    if (!seen(v, w.x, w.y, S, S)) continue;
    const a = lightLevel(w, lt, 0.5);
    if (a > 0.05) g.rect(w.x, w.y, S, S, w.col, a * 0.45);
  }
}

// On/off level of one light: each window keeps its state for a while, then
// fades to its next state. Lights switch on one by one during the first 1.5 s.
// Light constants (period, phase, switch-on time) are precomputed by `light()`.
function light(o) {
  o.p = 7 + hash(o.id, 3) * 22; o.ph = hash(o.id, 4); o.on = hash(o.id, 7) * 1.5;
  return o;
}

function lightLevel(w, lt, odds) {
  if (lt < w.on) return 0;
  const k = lt / w.p + w.ph, e = Math.floor(k), f = k - e;
  const cur = hash(w.id, 100 + e) < odds ? 1 : 0;
  const level = f < 0.9 ? cur : lerp(cur, hash(w.id, 101 + e) < odds ? 1 : 0, smoothstep(0.9, 1, f));
  return lt < w.on + 0.25 ? level * smoothstep(w.on, w.on + 0.25, lt) : level;
}

function drawMid(g, L, H, lt, v) {
  for (const b of L.mid) {
    if (b.x + b.w < v.l || b.x > v.r) continue;
    g.rect(b.x, b.top, b.w, b.h + 400, b.body);
    g.rect(b.x, b.top, b.w, S, '#3d2b6e');
    g.rect(b.x + S, b.top - S * 2, S * 3, S * 2, b.body);       // roof box
  }
  for (const w of L.windows) {
    if (!seen(v, w.x, w.y, S * 2, S * 2)) continue;
    let a = lightLevel(w, lt, 0.4);
    if (w.tv) a *= 0.55 + 0.45 * noise(w.id, lt * 2.5);         // a TV flickering inside
    if (a > 0.05) g.rect(w.x, w.y, S * 2, S * 2, w.col, a * 0.85);
  }
  for (const s of L.signs) {
    const h = S * (s.glyphs.length * 4 + 1);
    if (seen(v, s.x - h, s.y - h, S * 5 + 2 * h, 3 * h)) drawSign(g, s, lt); // glow reaches ~h
  }
}

function drawSign(g, s, lt) {
  const n = s.glyphs.length, h = S * (n * 4 + 1), w = S * 5;
  const on = smoothstep(0.6 + s.id % 5 * 0.15, 1 + s.id % 5 * 0.15, lt);
  // Steady neon with a soft hum and an occasional slow dip, no strobe.
  let a = (0.82 + 0.18 * noise(s.id, lt * 2)) * (1 - 0.55 * smoothstep(0.45, 0.7, noise(s.id * 3.1, lt * 0.35)));
  a *= on;
  if (on <= 0) return;
  g.glow(s.x + w / 2, s.y + h / 2, h * 0.9, s.col, 0.16 * a);
  g.rect(s.x, s.y, w, h, '#241a48', 0.85 * on); // backing fades in with the sign, never a black box
  g.rect(s.x, s.y, w, S, s.col, a); g.rect(s.x, s.y + h - S, w, S, s.col, a);
  g.rect(s.x, s.y, S, h, s.col, a * 0.8); g.rect(s.x + w - S, s.y, S, h, s.col, a * 0.8);
  for (const [c, r, n] of signRuns(s)) {
    g.rect(s.x + S * (1 + c), s.y + S * (1 + r), S * n, S, TN.fg, a * 0.9);
  }
}

// A sign's lit glyph pixels merged into horizontal runs, found on first use:
// one rect per run instead of one per pixel, the same picture.
function signRuns(s) {
  if (!s.runs) {
    s.runs = [];
    s.glyphs.forEach((bits, k) => {
      for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
        if (!(bits & (1 << (r * 3 + c)))) continue;
        let n = 1;
        while (c + n < 3 && bits & (1 << (r * 3 + c + n))) n++;
        s.runs.push([c, k * 4 + r, n]);
        c += n - 1;
      }
    });
  }
  return s.runs;
}

function drawPlane(g, W, H, lt) {
  const k = (lt / 46 + 0.35) % 1;
  if (k > 0.6) return;                                        // off screen most of the cycle
  const x = lerp(-60, W + 60, k / 0.6), y = H * (0.14 - 0.05 * k);
  g.rect(x, y, 2, 2, TN.fg, 0.55);
  const blink = smoothstep(0.55, 1, Math.sin(lt * 3.2));
  g.rect(x - 6, y + 1, 2, 2, TN.red, 0.2 + 0.8 * blink);
  g.glow(x - 5, y + 2, 7, TN.red, 0.2 * blink);
}

function drawTrack(g, L, W, H, lt) {
  const y = L.trackY;
  for (const px of L.pillars) g.rect(px, y + S * 2, S * 3, H - y, '#160f2c');
  // A Yamanote-green train crosses every 26 s, taking 9 s.
  const k = ((lt - 4) / 26) % 1;
  if (lt > 4 && k < 0.35) {
    const cars = 6, carW = S * 26, len = cars * (carW + S);
    const x0 = lerp(-len, (lt < WIDE_AT ? L.cityRight : W) + S * 10, k / 0.35), ty = y - S * 7;
    // Never snap moving things to the art grid: S-pixel jumps judder (GUIDE.md).
    for (let c = 0; c < cars; c++) {
      const cx = x0 + c * (carW + S);
      if (cx > L.cityRight || cx + carW < 0) continue;
      g.rect(cx, ty, carW, S * 7, '#2a2552');
      g.rect(cx, ty, carW, S, '#46407a');
      g.rect(cx, ty + S * 5, carW, S, TN.cyan, 0.85);
      for (let wx = 2; wx < 24; wx += 4) g.rect(cx + S * wx, ty + S * 2, S * 3, S * 2, '#e6ecff', 0.8);
    }
    const head = x0 + len;
    g.glow(head, ty + S * 4, 40, '#e6ecff', 0.22);
  }
  g.rect(-S, y, L.cityRight + S * 2, S * 2, '#1c1638');
  g.rect(-S, y, L.cityRight + S * 2, S, '#3d2b6e');
}

function drawNear(g, L, W, H, lt) {
  for (const r of L.roofs) {
    const top = H - r.h;
    g.rect(r.x, top, r.w, r.h + 400, '#130e26');
    g.rect(r.x, top, r.w, S, '#33265c');
    if (r.tank) {                                             // water tank on legs
      const tx = r.x + S * 3;
      g.rect(tx + S, top - S * 4, S, S * 4, '#130e26'); g.rect(tx + S * 6, top - S * 4, S, S * 4, '#130e26');
      g.rect(tx, top - S * 11, S * 8, S * 7, '#1a1333'); g.rect(tx, top - S * 11, S * 8, S, '#33265c');
      g.rect(tx + S, top - S * 12, S * 6, S, '#1a1333');
    }
    if (r.ac) {                                               // AC unit with a tiny status light
      const ax = r.x + r.w - S * 9;
      g.rect(ax, top - S * 3, S * 6, S * 3, '#1a1333'); g.rect(ax, top - S * 3, S * 6, S, '#33265c');
      const a = 0.4 + 0.6 * smoothstep(0, 1, 0.5 + 0.5 * Math.sin(lt * 0.8 + r.id));
      g.rect(ax + S * 4, top - S * 2, S, S, TN.green, a);
    }
  }
  // The Mapache's ledge: a parapet with a faint magenta neon trim.
  const l = L.ledge, top = H - l.h;
  g.rect(l.x, top, l.w, l.h + 400, '#110c24');
  g.rect(l.x, top, l.w, S, '#3a2a66');
  g.rect(l.x, top + S, l.w, S, TN.mag, 0.35 + 0.08 * noise(3, lt * 0.8));
  g.glow(l.x + (W - l.x) / 2, top + S, (W - l.x) * 0.5, TN.mag, 0.08);
  // Poles and wires.
  for (const p of L.poles) {
    g.rect(p[0], p[1] - S * 2, S * 2, H - p[1] + S * 2, '#0f0a1f');
    g.rect(p[0] - S * 3, p[1], S * 8, S, '#0f0a1f');
  }
  for (const w of L.wires) g.polyline(w, '#0c0818', 0.9, 2);
}

function drawPetals(g, L, W, H, lt) {
  // Wrap well outside the window so neither a petal nor its glow pops in.
  const span = H + 100, spanX = W + 80;
  const bloom = smoothstep(sakuraIn(), WIDE_AT + 1.5, lt);
  for (const p of L.petals) {
    // Blossom-born petals wait for the branches (see sakuraIn).
    if (p.source && lt < sakuraIn()) continue;
    const fall = [9, 16, 28][p.tier] * (0.8 + 0.4 * p.sp);
    let x, y, fade = 1;
    const wind = noise(p.i, lt * 0.12);
    if (p.source) {
      // Detach at a real blossom, then let the breeze take hold. Stagger
      // the loops from frame zero; recycle only once below the bottom edge.
      const drop = H + 30 - p.source.y, distance = (p.y0 * drop + lt * fall) % drop;
      x = p.source.x + distance * (1.1 + 0.5 * p.sp) + 48 * wind * Math.min(1, distance / 40);
      y = p.source.y + distance;
      // Fade in with the branches, and grow out of the blossom on each loop.
      fade = bloom * smoothstep(0, 24, distance);
    } else {
      y = (p.y0 * span + lt * fall) % span - 50;
      x = ((p.x0 * spanX + lt * fall * 0.9 + 60 * wind) % spanX + spanX) % spanX - 40;
    }
    // One spin drives both the frame and the mirror, so the petal turns over
    // exactly when it is edge-on: open, half, edge, then the other face.
    const spin = Math.sin(lt * p.spin + p.i), turn = Math.abs(spin);
    const art = PETALS[p.tier][turn > 0.66 ? 0 : turn > 0.33 ? 1 : 2];
    const a = [0.45, 0.7, 0.95][p.tier] * fade;
    if (a <= 0.01) continue;
    if (p.tier === 2) g.glow(x, y, 26, TN.rose, 0.18 * fade);
    // Centered on the frame: the tumble never shifts the petal's position.
    g.pixels(art, x - art.w * S / 2, y - art.h * S / 2, S, a, spin < 0);
  }
}

function drawPetalWipe(g, W, H, lt) {
  if (lt <= WIPE_IN || lt >= WIPE_OUT) return;
  const enter = smoothstep(WIPE_IN, COVER_AT, lt), exit = smoothstep(REVEAL_AT, WIPE_OUT, lt);
  const glide = smoothstep(WIPE_IN, WIPE_OUT, lt) - 0.5;
  // Overscan both dimensions: the opaque face, not just its transparent
  // bounding box, must hide the start of the pull-back on any aspect ratio.
  // Taller windows need more height: the blade tapers toward its claw.
  const art = WIPE_PETAL, peak = Math.max(1.34 * W / art.w, 1.8 * H / art.h);
  const size = peak * (lerp(0.065, 1, enter * enter) + 0.12 * exit);
  const x = lerp(-2 * peak, W / 2, enter) + (W / 2 + art.w * peak * 0.85) * exit + W * 0.06 * glide;
  const y = H * (lerp(0.89, 0.50, enter) - 0.09 * Math.sin(Math.PI * enter) - 0.33 * exit);
  // The halo trails the rim; a little roll and drift carry on through the hold.
  g.glow(x - size * 4, y + size, art.w * size * 0.62, TN.rose, 0.20);
  g.save();
  g.translate(x, y);
  g.rotate(-1.18 + 1.06 * enter + 0.59 * exit + 0.15 * glide);
  g.scale(1, lerp(0.36, 1, enter) - 0.38 * exit);
  // Pivot on the widest part of the blade, not the box centre.
  g.pixels(art, -art.w * size / 2, -art.h * size * 0.42, size);
  g.restore();
}

SCENES['mapache-neon-tokyo'] = {
  draw(g, t) {
    if (first === null) first = t;
    const lt = t - first, W = g.width, H = g.height;
    const key = W + 'x' + H;
    if (key !== layoutKey) { layout = buildLayout(W, H); layoutKey = key; }
    const L = layout, cam = camera(lt);

    drawStars(g, L, lt);
    drawCityGlow(g, W, H, lt);
    drawMoonAndClouds(g, W, H, lt);

    g.save(); applyCamera(g, cam, 0.6, W, H);
    g.pixels(FUJI, W * 0.50 - FUJI.w * S / 2, Math.max(H * 0.29, H * 0.69 - FUJI.h * S), S, 0.94);
    const farLeft = W / 2 + (cam.x * 0.6 - W / 2) / (1 + (cam.z - 1) * 0.6);
    drawTowers(g, L, lt, farLeft);
    drawFar(g, L, lt, viewOf(cam, 0.6, W, H));
    // Haze between far and mid: separates the layers and sells the distance.
    g.gradient(-W, L.farY - H * 0.16, W * 3, H * 0.3, 180, '#3a226600', '#3a2266aa');
    g.restore();

    g.save(); applyCamera(g, cam, 0.85, W, H);
    drawMid(g, L, H, lt, viewOf(cam, 0.85, W, H));
    g.restore();

    g.save(); applyCamera(g, cam, 0.92, W, H);
    drawTrack(g, L, W, H, lt);
    g.restore();

    g.save(); applyCamera(g, cam, 1, W, H);
    drawNear(g, L, W, H, lt);
    g.save(); g.resetTransform();
    drawSakura(g, L, lt);
    g.restore();
    drawHero(g, L, H, lt);
    g.restore();

    drawPlane(g, W, H, lt);
    drawPetals(g, L, W, H, lt);
    if (lt >= RELEASE && lt < 11) drawLoosePetals(g, W, H, lt);
    if (DEBUG_LINEUP) drawLineup(g, W, H);
    drawPetalWipe(g, W, H, lt);
  },
};
